-- c004-v007: e a paz de Deus a que–excede todo entendimento guardará os corações vossos e os pensamentos vossos em Cristo Jesus
-- c004-v008: quanto–ao mais irmãos tudo–o–que é verdadeiro tudo–o–que é–respeitável tudo–o–que é–justo tudo–o–que é–puro tudo–o–que é–amável tudo–o–que é–de–boa–fama se alguma virtude e se algum louvor nestas–coisas pensai
-- c004-v009: o–que também aprendestes e recebestes e ouvistes e vistes em mim estas–coisas praticai e o Deus da paz estará convosco vós
-- c004-v010: alegrei–me porém no Senhor grandemente que já agora reflorescestes o de mim cuidar em que também cuidáveis mas–faltava–oportunidade porém
-- c004-v011: não que por necessidade digo eu pois aprendi em qualquer–situação estou contente estar
-- c004-v012: sei tanto ser–humilhado sei também ter–abundância em toda e em todas–as–circunstâncias tenho–aprendido–o–segredo tanto de–fartar–me como de–ter–fome tanto de–ter–abundância como de–sofrer–necessidade
-- c004-v013: tudo posso naquele que me–fortalece me
-- c004-v014: contudo bem fizestes participando da–minha na tribulação
-- c004-v015: sabeis porém também vós filipenses que no princípio do evangelho quando saí da Macedônia nenhuma comigo igreja compartilhou em matéria de–dar e de–receber se–não não vós sós
-- c004-v016: porque também em Tessalônica tanto uma–vez como duas–vezes para a necessidade a–mim enviastes
-- c004-v017: não que busco a dádiva mas busco o fruto o que–aumenta para conta vossa
-- c004-v018: tenho–recebido porém tudo e tenho–abundância estou–cheio tendo–recebido de Epafrodito as–coisas de vós aroma suave sacrifício agradável agradabilíssimo a Deus
-- c004-v019: o porém Deus meu suprirá toda necessidade vossa segundo as riquezas dele em glória em Cristo Jesus
-- c004-v020: ao porém Deus e Pai nosso seja–a glória pelos os séculos dos séculos amém
-- c004-v021: saudai a–todo santo em Cristo Jesus saúdam–vos vós os comigo comigo irmãos
